def name_operands(region,address,operation):
 if region!='Station' or address!=0x6D0D:return operation
 for value,name in ((0xAEBB,'TextWindow.OriginXLow'),(0xAEC7,'TextWindow.OriginYLow'),(0x788D,'VariantPanelState.ItemIndex')):operation=operation.replace('(#'+format(value,'04X')+')','(@'+name+')')
 return operation.replace('LD A, #11','LD A, @SystemNameConst.MapPage').replace('LD A, #10','LD A, @StationIrqConst.StationPage')
